/** 
 * Upload certificate and eventually private key
 * @param uriInfo
 * @param input
 * @return
 * @throws IOException
 */
@POST @Path("upload") @Consumes(MediaType.MULTIPART_FORM_DATA) @Produces(MediaType.APPLICATION_JSON) public CertificateRepresentation uploadJks(@Context final UriInfo uriInfo, MultipartFormDataInput input) throws IOException {
  auth.requireManage();
  if (client == null) {
    throw new NotFoundException("Could not find client");
  }
  CertificateRepresentation info;
  try {
    info = getCertFromRequest(uriInfo, input);
  } catch (RuntimeException e) {
    throw new ErrorResponseException("parse-error", "Failed to parse certificate or key from request: " + e.getMessage(), Response.Status.BAD_REQUEST);
  }
  if (info.getPrivateKey() != null) {
    client.setAttribute(privateAttribute, info.getPrivateKey());
  }
  else if (info.getCertificate() != null) {
    client.removeAttribute(privateAttribute);
  }
  else {
    throw new ErrorResponseException("certificate-not-found", "Certificate or key with given alias not found in the keystore", Response.Status.BAD_REQUEST);
  }
  if (info.getCertificate() != null) {
    client.setAttribute(certificateAttribute, info.getCertificate());
  }
  adminEvent.operation(OperationType.ACTION).resourcePath(session.getContext().getUri()).representation(info).success();
  return info;
}
